from html.parser import HTMLParser
from pathlib import Path
import re, xml.etree.ElementTree as ET
class Check(HTMLParser):
 def __init__(self): super().__init__(); self.ids=[]; self.links=[]; self.stack=[]; self.errors=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if 'id' in d:self.ids.append(d['id'])
  if t=='a' and d.get('href','').startswith('#') and len(d['href'])>1:self.links.append(d['href'][1:])
  if t not in ['area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr']:self.stack.append(t)
 def handle_endtag(self,t):
  if self.stack and self.stack[-1]==t:self.stack.pop()
  else:self.errors.append((t,self.stack[-3:]))
s=Path('index.html').read_text(); c=Check();c.feed(s)
assert not c.errors, c.errors
assert not c.stack, c.stack
assert len(c.ids)==len(set(c.ids)), 'Duplicate IDs'
assert not set(c.links)-set(c.ids), 'Broken fragment links'
for svg in re.findall(r'<svg\\b.*?</svg>',s,re.S): ET.fromstring(svg)
assert len(re.findall(r'class=\"project\"',s))==4
assert len(re.findall(r'class=\"post\"',s))==6
assert 'src=\"http' not in s
print('PASS: balanced HTML, unique IDs, fragment links, 7 valid inline SVGs, 4 projects, 6 posts, no remote images.')
def lum(h):
 vals=[int(h[i:i+2],16)/255 for i in (0,2,4)]
 return sum(a*b for a,b in zip([v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in vals],[.2126,.7152,.0722]))
for label,fg,bg in [('Light text','262925','f8f7f3'),('Light muted','686b65','f8f7f3'),('Light blue','244cbd','f8f7f3'),('Dark text','eeeee6','1b201f'),('Dark muted','b1b8ae','1b201f'),('Dark blue','a5bdff','1b201f'),('Article muted light','686b65','e9edf7'),('Article muted dark','b1b8ae','252f40'),('Panel muted','d1daf0','213d79')]:
 a,b=sorted([lum(fg),lum(bg)]);r=(b+.05)/(a+.05);assert r>=4.5,(label,r);print(label,round(r,2))
