/bin/zsh -lc "node <<'JS'
const fs=require('fs'),vm=require('vm'),assert=require('assert');
const html=fs.readFileSync('index.html','utf8');
class El{constructor(attrs={}){this.attrs=attrs;this.dataset={};this.listeners={};this.value='';this.className='';this.textContent='';this.hidden=false;this.focused=false}setAttribute(k,v){this.attrs[k]=v}getAttribute(k){return this.attrs[k]}removeAttribute(k){delete this.attrs[k]}hasAttribute(k){return k in this.attrs}addEventListener(k,f){this.listeners[k]=f}fire(k){this.listeners[k]({preventDefault(){}})}focus(){this.focused=true}}
const root={dataset:{theme:'light'}}, storage={};
const ids=Object.fromEntries(['theme-toggle','filter-status','newsletter-form','newsletter-email','newsletter-message'].map(id=>[id,new El()]));
const filters=['All','Design','Data','Freelancing','Field notes'].map(t=>{const e=new El();e.dataset.filter=t;return e});
const posts=['Design','Field notes','Design','Data','Field notes','Freelancing'].map(t=>{const e=new El();e.dataset.tag=t;return e});
const meta={};
const doc={documentElement:root,getElementById:id=>ids[id],querySelector:()=>meta,querySelectorAll:s=>s==='.filter'?filters:posts};
const ctx={document:doc,localStorage:{setItem:(k,v)=>storage[k]=v}};
const scripts=[...html.matchAll(/<script>([\\s\\S]*?)<\\/script>/g)].map(m=>m[1]);
new vm.Script(scripts[1]).runInNewContext(ctx);
ids['theme-toggle'].fire('click');assert.equal(root.dataset.theme,'dark');assert.equal(ids['theme-toggle'].attrs['aria-pressed'],'true');assert.equal(storage['maya-theme'],'dark');
ids['theme-toggle'].fire('click');assert.equal(root.dataset.theme,'light');
for(const [index,count] of [[1,2],[2,1],[3,1],[4,2],[0,6]]){filters[index].fire('click');assert.equal(posts.filter(p=>"'!p.hidden).length,count);assert.equal(filters.filter(f=>f.attrs['"'aria-pressed']==='true').length,1)}
const email=ids['newsletter-email'];email.validity={valid:false};ids['newsletter-form'].fire('submit');assert.equal(email.attrs['aria-invalid'],'true');assert.equal(email.focused,true);
email.value='reader@example.com';email.validity.valid=true;email.fire('input');assert.equal(email.attrs['aria-invalid'],undefined);ids['newsletter-form'].fire('submit');assert(ids['newsletter-message'].textContent.includes('has not been submitted or stored'));
assert.equal(Object.keys(storage).length,1);
console.log('PASS: theme switching and persistence, all topic filters and result counts, email validation and focus, honest standalone form feedback.');
JS"

